1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"sort"
7		"time"
8	)
9	
10	// 升级阶段标识。
11	const (
12		StageDownload = "download"
13		StageInstall  = "install"
14	)
15	
16	// 活动与设备在活动中的状态。
17	const (
18		CampaignRunning   = "running"
19		CampaignSucceeded = "succeeded"
20		CampaignFailed    = "failed"
21	
22		DevicePending     = "pending"     // 尚未领取下载
23		DeviceDownloading = "downloading" // 已领取下载，未完成
24		DeviceReady       = "ready"       // 下载成功，安装尚未领取
25		DeviceInstalling  = "installing"  // 已领取安装，未完成
26		DeviceSucceeded   = "succeeded"
27		DeviceFailed      = "failed"
28		DeviceTimeout     = "timeout"
29		DeviceSkipped     = "skipped" // 前序批次失败后，后续批次记为未执行
30	)
31	
32	// VersionSpec 是一个已登记的升级目标版本及其允许的当前版本。
33	type VersionSpec struct {
34		// Target 是目标版本，与设备当前版本按字符串精确匹配。
35		Target string
36		// AllowedFrom 是允许升级到目标版本的当前版本列表。
37		AllowedFrom []string
38	}
39	
40	// versionState 是升级版本登记的内部状态。
41	type versionState struct {
42		Target      string
43		AllowedFrom []string
44	}
45	
46	// CampaignSpec 描述创建分批升级活动所需的全部信息。
47	type CampaignSpec struct {
48		// ID 是活动唯一标识，不能为空。
49		ID string
50		// Operator 是创建活动的操作者，不能为空。
51		Operator string
52		// CreatedAt 是活动创建时间。
53		CreatedAt time.Time
54		// TargetVersion 是已登记的目标版本。
55		TargetVersion string
56		// Devices 是按提交次序排列的有序设备列表，不能为空、不能重复。
57		Devices []string
58		// BatchSize 是批大小，必须是正整数。
59		BatchSize int
60		// WindowStart/WindowEnd 是维护窗口，开始时刻须早于结束时刻；
61		// 窗口包含开始时刻、不包含结束时刻。
62		WindowStart time.Time
63		WindowEnd   time.Time
64		// Deadline 是截止时间，必须晚于创建时间。
65		Deadline time.Time
66	}
67	
68	// Operation 是派发给设备的一个升级操作。
69	type Operation struct {
70		// ID 是操作的稳定标识，重复查询未完成操作时保持不变，重开存储后仍有效。
71		ID         string
72		CampaignID string
73		DeviceID   string
74		// Kind 是 StageDownload 或 StageInstall。
75		Kind string
76	}
77	
78	// OperationResult 是设备提交的一次操作结果。
79	// 每次结果必须带活动、设备、操作标识及发生时间。
80	// 安装成功（Success 且操作是 install）时还须附带符合上报规则的设备上报：
81	// 正整数 Seq、等于目标版本的 Version 和完整 JSON 对象 Config。
82	type OperationResult struct {
83		CampaignID  string
84		DeviceID    string
85		OperationID string
86		At          time.Time
87		Success     bool
88		// Reason 在失败时必填。
89		Reason string
90		// 安装成功时附带的设备上报。
91		Seq     uint64
92		Version string
93		Config  json.RawMessage
94	}
95	
96	// ResultRecord 是结果历史中的一条记录，按接受顺序保存。
97	type ResultRecord struct {
98		DeviceID    string
99		OperationID string
100		Stage       string
101		Success     bool
102		Reason      string
103		// Version 为安装成功时上报的目标版本，其余为空。
104		Version string
105		At      time.Time
106	}
107	
108	// opState 是单个设备单个阶段的操作与结果状态。
109	type opState struct {
110		ID string
111		// Claimed 表示操作是否已被领取；未领取的操作不能提交结果。
112		Claimed   bool
113		ClaimedAt time.Time
114		// 已接受的结果。
115		HasResult     bool
116		Success       bool
117		Reason        string
118		At            time.Time
119		ResultSeq     uint64
120		ResultVersion string
121		ResultConfig  json.RawMessage
122	}
123	
124	// campaignDevice 是单台设备在一个活动中的完整状态。
125	type campaignDevice struct {
126		DeviceID string
127		Batch    int
128		Download opState
129		Install  opState
130		// Status/Phase/Reason/At 描述设备当前状态；
131		// failed 必须记录阶段、原因和时间；timeout/skipped 同理。
132		Status string
133		Phase  string
134		Reason string
135		At     time.Time
136	}
137	
138	// campaignState 是一个分批升级活动的内部状态。
139	type campaignState struct {
140		ID          string
141		Operator    string
142		Target      string
143		CreatedAt   time.Time
144		BatchSize   int
145		WindowStart time.Time
146		WindowEnd   time.Time
147		Deadline    time.Time
148		Devices     []*campaignDevice
149		index       map[string]int
150		Results     []ResultRecord
151		// LastTime 是本活动已接受的最晚时间，用于拒绝时间倒退。
152		LastTime time.Time
153		Status   string
154		Ended    bool
155		EndedAt  time.Time
156	}
157	
158	// RegisterUpgrade 登记一个升级目标版本及允许升级的当前版本列表。
159	// 版本字符串精确匹配；列表不能为空、不能含空串、不能包含目标版本。
160	// 目标版本重复登记时返回 ErrVersionExists 并保留原记录。
161	func (s *Store) RegisterUpgrade(targetVersion string, allowedFrom []string) error {
162		s.mu.Lock()
163		defer s.mu.Unlock()
164		if err := s.checkOpen(); err != nil {
165			return err
166		}
167		if targetVersion == "" {
168			return ErrInvalidVersion
169		}
170		if err := validateAllowedFrom(targetVersion, allowedFrom); err != nil {
171			return err
172		}
173		if _, ok := s.versions[targetVersion]; ok {
174			return fmt.Errorf("%w: %s", ErrVersionExists, targetVersion)
175		}
176		from := append([]string(nil), allowedFrom...)
177		return s.commit(func() error {
178			s.versions[targetVersion] = &versionState{Target: targetVersion, AllowedFrom: from}
179			return nil
180		})
181	}
182	
183	func validateAllowedFrom(target string, allowedFrom []string) error {
184		if len(allowedFrom) == 0 {
185			return fmt.Errorf("%w: list is empty", ErrInvalidVersionList)
186		}
187		for _, v := range allowedFrom {
188			if v == "" {
189				return fmt.Errorf("%w: contains empty version", ErrInvalidVersionList)
190			}
191			if v == target {
192				return fmt.Errorf("%w: contains target version %s", ErrInvalidVersionList, target)
193			}
194		}
195		return nil
196	}
197	
198	// CreateCampaign 创建分批升级活动。任何必填信息缺失、设备或目标版本未登记、
199	// 设备当前版本不兼容或设备已参加未结束活动时，整次创建失败，不留下部分记录。
200	func (s *Store) CreateCampaign(spec CampaignSpec) error {
201		s.mu.Lock()
202		defer s.mu.Unlock()
203		if err := s.checkOpen(); err != nil {
204			return err
205		}
206		// 先做全部校验，全部通过后才写入，保证原子创建。
207		if spec.ID == "" {
208			return ErrInvalidCampaignID
209		}
210		if spec.Operator == "" {
211			return ErrInvalidOperator
212		}
213		if spec.CreatedAt.IsZero() {
214			return fmt.Errorf("%w: created at", ErrInvalidTime)
215		}
216		if spec.WindowStart.IsZero() || spec.WindowEnd.IsZero() {
217			return fmt.Errorf("%w: maintenance window", ErrInvalidTime)
218		}
219		if spec.Deadline.IsZero() {
220			return fmt.Errorf("%w: deadline", ErrInvalidTime)
221		}
222		if len(spec.Devices) == 0 {
223			return ErrInvalidDeviceList
224		}
225		seen := make(map[string]bool, len(spec.Devices))
226		for _, id := range spec.Devices {
227			if id == "" {
228				return ErrInvalidDeviceID
229			}
230			if seen[id] {
231				return fmt.Errorf("%w: %s", ErrDuplicateDevice, id)
232			}
233			seen[id] = true
234		}
235		if spec.BatchSize <= 0 {
236			return ErrInvalidBatchSize
237		}
238		if !spec.WindowStart.Before(spec.WindowEnd) {
239			return ErrInvalidWindow
240		}
241		if !spec.Deadline.After(spec.CreatedAt) {
242			return ErrInvalidDeadline
243		}
244		if spec.TargetVersion == "" {
245			return ErrInvalidVersion
246		}
247		if _, ok := s.versions[spec.TargetVersion]; !ok {
248			return fmt.Errorf("%w: %s", ErrVersionNotFound, spec.TargetVersion)
249		}
250		if _, ok := s.campaigns[spec.ID]; ok {
251			return fmt.Errorf("%w: %s", ErrCampaignExists, spec.ID)
252		}
253		ver := s.versions[spec.TargetVersion]
254		devs := make([]*campaignDevice, 0, len(spec.Devices))
255		for i, id := range spec.Devices {
256			d, ok := s.devices[id]
257			if !ok {
258				return fmt.Errorf("%w: %s", ErrDeviceNotFound, id)
259			}
260			if !containsString(ver.AllowedFrom, d.Version) {
261				return fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, id, d.Version)
262			}
263			if s.deviceBusy(id, spec.ID) {
264				return fmt.Errorf("%w: %s", ErrDeviceBusy, id)
265			}
266			devs = append(devs, &campaignDevice{
267				DeviceID: id,
268				Batch:    i / spec.BatchSize,
269				Status:   DevicePending,
270				Phase:    StageDownload,
271				Download: opState{ID: operationID(spec.ID, id, StageDownload)},
272				Install:  opState{ID: operationID(spec.ID, id, StageInstall)},
273			})
274		}
275		campaign := &campaignState{
276			ID:          spec.ID,
277			Operator:    spec.Operator,
278			Target:      spec.TargetVersion,
279			CreatedAt:   spec.CreatedAt,
280			BatchSize:   spec.BatchSize,
281			WindowStart: spec.WindowStart,
282			WindowEnd:   spec.WindowEnd,
283			Deadline:    spec.Deadline,
284			Devices:     devs,
285			index:       make(map[string]int, len(devs)),
286			LastTime:    spec.CreatedAt,
287			Status:      CampaignRunning,
288		}
289		for i, cd := range devs {
290			campaign.index[cd.DeviceID] = i
291		}
292		return s.commit(func() error {
293			s.campaigns[spec.ID] = campaign
294			return nil
295		})
296	}
