298	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
299	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
300		for id, c := range s.campaigns {
301			if id == excludeCampaign || c.Ended {
302				continue
303			}
304			if _, ok := c.index[deviceID]; ok {
305				return true
306			}
307		}
308		return false
309	}
310	
311	func operationID(campaignID, deviceID, stage string) string {
312		return campaignID + ":" + deviceID + ":" + stage
313	}
314	
315	func containsString(list []string, v string) bool {
316		for _, x := range list {
317			if x == v {
318				return true
319			}
320		}
321		return false
322	}
