74	
75	func (s *Store) marshalCampaigns() (map[string]diskCampaign, error) {
76		out := make(map[string]diskCampaign, len(s.campaigns))
77		for id, c := range s.campaigns {
78			dc := diskCampaign{
79				ID:          c.ID,
80				Operator:    c.Operator,
81				Target:      c.Target,
82				CreatedAt:   c.CreatedAt,
83				BatchSize:   c.BatchSize,
84				WindowStart: c.WindowStart,
85				WindowEnd:   c.WindowEnd,
86				Deadline:    c.Deadline,
87				LastTime:    c.LastTime,
88				Status:      c.Status,
89				Ended:       c.Ended,
90				EndedAt:     c.EndedAt,
91				Results:     make([]diskResult, 0, len(c.Results)),
92			}
93			for _, cd := range c.Devices {
94				dc.Devices = append(dc.Devices, diskDev{
95					DeviceID: cd.DeviceID,
96					Batch:    cd.Batch,
97					Status:   cd.Status,
98					Phase:    cd.Phase,
99					Reason:   cd.Reason,
100					At:       cd.At,
101					Download: encodeOp(cd.Download),
102					Install:  encodeOp(cd.Install),
103				})
104			}
105			for _, r := range c.Results {
106				dc.Results = append(dc.Results, diskResult{
107					DeviceID:    r.DeviceID,
108					OperationID: r.OperationID,
109					Stage:       r.Stage,
110					Success:     r.Success,
111					Reason:      r.Reason,
112					Version:     r.Version,
113					At:          r.At,
