123			ID:            o.ID,
124			Claimed:       o.Claimed,
125			ClaimedAt:     o.ClaimedAt,
126			HasResult:     o.HasResult,
127			Success:       o.Success,
128			Reason:        o.Reason,
129			At:            o.At,
130			ResultSeq:     o.ResultSeq,
131			ResultVersion: o.ResultVersion,
132			ResultConfig:  cloneRaw(o.ResultConfig),
133		}
134	}
