			op.ResultVersion = res.Version
			op.ResultConfig = cloneRaw(res.Config)
			cd.Status = DeviceSucceeded
			cd.Phase = StageInstall
			cd.Reason = ""
			cd.At = res.At
		case StageRollback:
			// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
