			DeviceID:    cd.DeviceID,
			OperationID: op.ID,
			Stage:       stage,
			Success:     true,
			Version:     op.ResultVersion,
			At:          res.At,
		})
		s.settle(c, res.At)
		return nil
	})
	if err != nil {
		return err
	}
	return reject
}

